import json,ssl,urllib.request,subprocess
r={"audit":"public-health","credentials_opened":False,"media_requested":False}
try:
 with urllib.request.urlopen("https://serveriptv.duckdns.org/System/Info/Public",timeout=12,context=ssl.create_default_context()) as response:
  r["http_status"]=response.status
  r["jellyfin_version"]=json.load(response).get("Version")
except Exception as e:
 r["public_error_class"]=type(e).__name__
for service in ("jellyfin-pink.service","vivoapk-backend.service","nginx.service","postgresql.service"):
 r[service]=subprocess.run(["systemctl","is-active","--quiet",service],timeout=6).returncode==0
print(json.dumps(r,sort_keys=True),flush=True)
raise SystemExit(0 if r.get("http_status")==200 and all(r[s] for s in ("jellyfin-pink.service","vivoapk-backend.service","nginx.service","postgresql.service")) else 1)

import json,subprocess,os
from pathlib import Path
r={"audit":"read-only-project-inventory","credentials_opened":False,"media_requested":False,"removed":0}
for path in ("/srv/projects/Vivoapk","/srv/projects/jellyfin-server"):
 p=Path(path)
 try:
  r[p.name]={"exists":p.is_dir(),"top_level_directory_count":sum(x.is_dir() for x in p.iterdir()),"top_level_file_count":sum(x.is_file() for x in p.iterdir())}
 except OSError as e:
  r[p.name]={"exists":p.is_dir(),"inventory_error_class":type(e).__name__}
p=subprocess.run(["systemctl","list-unit-files","--type=service","--no-legend","--no-pager"],capture_output=True,text=True,timeout=10)
r["legacy_named_service_units"]=[line.split()[0] for line in p.stdout.splitlines() if line.split() and "pink" in line.split()[0].lower()]
r["service_inventory_exit"]=p.returncode
print(json.dumps(r,sort_keys=True),flush=True)
raise SystemExit(0 if p.returncode==0 and all("inventory_error_class" not in r.get(k,{}) for k in ("Vivoapk","jellyfin-server")) else 1)
